const dates = (function createDateHelpers() {
  const MILLISECONDS_PER_DAY = 86_400_000;

  function day(isoDate) {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(isoDate)) {
      throw Error("Data inválida");
    }

    const timestamp = Date.parse(isoDate + "T00:00:00Z");
    const isValid =
      Number.isFinite(timestamp) &&
      new Date(timestamp).toISOString().slice(0, 10) === isoDate;

    if (!isValid) {
      throw Error("Data inválida");
    }
    return timestamp;
  }

  function addMonths(isoDate, months) {
    const date = new Date(day(isoDate));
    const originalDay = date.getUTCDate();
    date.setUTCDate(1);
    date.setUTCMonth(date.getUTCMonth() + months);

    const lastDayOfMonth = new Date(
      Date.UTC(date.getUTCFullYear(), date.getUTCMonth() + 1, 0),
    ).getUTCDate();
    date.setUTCDate(Math.min(originalDay, lastDayOfMonth));
    return date.toISOString().slice(0, 10);
  }

  function tripDuration(departure, returnDate) {
    return (day(returnDate) - day(departure)) / MILLISECONDS_PER_DAY;
  }

  return { day, addMonths, tripDuration };
})({

});

const prices = (function createPriceHelpers({ text }) {
  function priceCents(value) {
    const normalizedPrice = text.normalize(value);
    const match = normalizedPrice.match(
      /^R\$\s*((?:\d{1,3}(?:\.\d{3})+|\d+))(?:,(\d{2}))?$/,
    );
    if (!match) {
      throw Error("Preço em BRL não reconhecido");
    }

    const reais = Number(match[1].replace(/\./g, ""));
    const cents = Number(match[2] || 0);
    const totalCents = reais * 100 + cents;
    if (!Number.isSafeInteger(totalCents) || totalCents <= 0) {
      throw Error("Preço inválido");
    }
    return totalCents;
  }

  return { priceCents };
})({
text: text
});

const protocol = (function createFlightProtocol() {
  const WIRE_TYPES = { INTEGER: 0, FIXED_64: 1, BYTES: 2, FIXED_32: 5 };
  const VARINT_BASE = 128;
  const VARINT_DATA_MASK = 127;
  const VARINT_CONTINUATION = 128;
  const MAX_VARINT_BYTES = 10;
  // These are encoded protobuf tags (field number * 8 + wire type), not field numbers.
  const TAGS = { FLIGHT_LEG: 26, DATE: 18, ORIGIN: 106, DESTINATION: 114 };

  function fields(bytes) {
    let offset = 0;
    const result = [];

    function readInteger() {
      let value = 0;
      let shift = 0;
      for (let index = 0; index < MAX_VARINT_BYTES; index += 1) {
        if (offset >= bytes.length) {
          throw Error("Parâmetro truncado");
        }
        const byte = bytes[offset++];
        value += (byte & VARINT_DATA_MASK) * 2 ** shift;
        if (!(byte & VARINT_CONTINUATION)) {
          return value;
        }
        shift += 7;
      }
      throw Error("Parâmetro inválido");
    }

    while (offset < bytes.length) {
      const start = offset;
      const key = readInteger();
      const wireType = key % 8;
      let data;

      if (wireType === WIRE_TYPES.BYTES) {
        const length = readInteger();
        if (!Number.isSafeInteger(length) || offset + length > bytes.length) {
          throw Error("Comprimento inválido");
        }
        data = bytes.subarray(offset, offset + length);
        offset += length;
      } else if (wireType === WIRE_TYPES.INTEGER) {
        readInteger();
      } else if (wireType === WIRE_TYPES.FIXED_64) {
        offset += 8;
      } else if (wireType === WIRE_TYPES.FIXED_32) {
        offset += 4;
      } else {
        throw Error("Formato de parâmetro desconhecido");
      }

      if (offset > bytes.length) {
        throw Error("Parâmetro truncado");
      }
      result.push({ key, data, raw: bytes.subarray(start, offset) });
    }
    return result;
  }

  function encodeInteger(value) {
    const bytes = [];
    do {
      const continuation = value >= VARINT_BASE ? VARINT_CONTINUATION : 0;
      bytes.push((value % VARINT_BASE) | continuation);
      value = Math.floor(value / VARINT_BASE);
    } while (value);
    return Buffer.from(bytes);
  }

  function field(tag, data) {
    return Buffer.concat([encodeInteger(tag), encodeInteger(data.length), data]);
  }

  function airportLocation(origin) {
    // The public URL represents an IATA airport as location type 1 and a three-byte code.
    return Buffer.from([8, 1, 18, 3, ...Buffer.from(origin)]);
  }

  function integerField(tag, value) {
    if (!Number.isSafeInteger(value) || value < 0) {
      throw Error("Inteiro inválido");
    }
    return Buffer.concat([encodeInteger(tag), encodeInteger(value)]);
  }

  return { fields, field, integerField, airportLocation, tags: TAGS };
})({

});

const flightDateParser = (function createFlightDateParser({ protocol, dates }) {
  function readLegDate(leg) {
    const dateFields = protocol.fields(leg.data).filter(({ key }) => key === protocol.tags.DATE);
    if (dateFields.length !== 1) {
      throw Error("Data ambígua");
    }
    const isoDate = dateFields[0].data.toString("utf8");
    dates.day(isoDate);
    return isoDate;
  }

  function flightDates(url) {
    const encodedQuery = url.match(/[?&]tfs=([^&]+)/)?.[1];
    if (!encodedQuery) {
      throw Error("Link sem datas verificáveis");
    }
    const queryBytes = Buffer.from(decodeURIComponent(encodedQuery), "base64url");
    const legs = protocol.fields(queryBytes).filter(({ key }) => key === protocol.tags.FLIGHT_LEG);
    if (legs.length !== 2) {
      throw Error("Oferta não comprova ida e volta");
    }
    return legs.map(readLegDate);
  }

  return { flightDates };
})({
protocol: protocol,
dates: dates
});

const settings = (function createSettings() {
  return {
    categories: ["nacionais", "internacionais"],
    origins: ["GRU", "CGH"],
    timezone: "America/Sao_Paulo",
    currency: "BRL",
    horizonMonths: 6,
    minimumTripDays: 3,
    maximumTripDays: 14,
    offerLimit: 10,
    maximumAttempts: 3,
    retryDelaySeconds: 3,
    requestTimeoutMs: 60_000,
    executionTimeoutSeconds: 1_200,
    userAgent:
      "Mozilla/5.0 (X11; Linux x86_64) AppleWebKit/537.36 " +
